sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    // =====================================================
    // 1. SINGLE STUDENT APPLICATION MODE
    //    Do NOT create interviews for all applications.
    // =====================================================

    if (current.getValue('u_single_student_application') == 'true') {
        return;
    }


    // =====================================================
    // 2. DRIVE IS REQUIRED FOR DRIVE AUTOMATION
    // =====================================================

    if (!current.getValue('drive')) {
        return;
    }


    // =====================================================
    // 3. GET APPLICATIONS BELONGING TO THIS DRIVE
    // =====================================================

    var appGr = new GlideRecord('x_snc_college_pl_0_application');

    appGr.addQuery('drive', current.getValue('drive'));
    appGr.query();


    // =====================================================
    // 4. CREATE INTERVIEW FOR EACH APPLICATION
    // =====================================================

    while (appGr.next()) {

        var intGr = new GlideRecord('x_snc_college_pl_0_interview');

        intGr.initialize();

        intGr.setValue('drive', current.getValue('drive'));
        intGr.setValue('application', appGr.getUniqueValue());
        intGr.setValue('round_name', current.getValue('round_name'));
        intGr.setValue('interview_date', current.getValue('interview_date'));
        intGr.setValue('interviewer', current.getValue('interviewer'));

        // Prevent the newly-created Interview from
        // triggering Business Rules again.
        intGr.setWorkflow(false);

        intGr.insert();
    }

})(current, previous);
